const assert=require('node:assert/strict');const e=require('../../school/toolkit_english.js');assert.equal(e.phrases.length,40);assert.equal(new Set(e.phrases.map(p=>p[0])).size,40);for(const p of e.phrases){assert.equal(p.length,4);assert(p.every(v=>typeof v==='string'&&v.length));}assert.deepEqual(e.today('2026-10-16'),e.today('2026-10-16'));assert(e.phrases.includes(e.today('2026-10-17')));assert.equal(e.say('test'),false);console.log('40 bilingual classroom phrases and optional audio checked');
